# console keymap for the Colemak Mod-DH layout (US, ANSI keyboard, Z angle mod, Wide layout).
# http://colemakmods.github.io/mod-dh/.
# Public domain.

# keycodes seem to be xev - 8

alt_is_meta
charset "iso-8859-15"  # use a ISO-8859-15 font, e.g.: consolechars -f lat9v-14
keymaps 0-12
include "qwerty-layout"
include "linux-with-alt-and-altgr"
strings as usual

# don't shift over numbers
keycode  41  =  grave  asciitilde  grave  asciitilde
keycode  2   =  one    exclam      one    exclam
keycode  3   =  two    at          two    at
keycode  4   =  three  numbersign  three  numbersign
keycode  5   =  four   dollar      four   dollar
keycode  6   =  five   percent     five   percent
keycode  7   =  six    asciicircum six    asciicircum
keycode  8   =  seven  ampersand   seven  ampersand
keycode  9   =  eight  asterisk    eight  asterisk
keycode  10  =  nine   parenleft   nine   parenleft
keycode  11  =  zero   parenright  zero   parenright
keycode  12  =  minus  underscore  minus  underscore
keycode  13  =  equal  plus        equal  plus

keycode  16  =  q            Q         q            Q
keycode  17  =  w            W         w            W
keycode  18  =  f            F         e            E
keycode  19  =  p            P         r            R
keycode  20  =  b            B         t            T
keycode  21  =  bracketleft  braceleft y            Y
keycode  22  =  j            J         u            U
keycode  23  =  l            L         i            I
keycode  24  =  u            U         o            O
keycode  25  =  y            Y         p            P
keycode  26  =  semicolon    colon     bracketleft  braceleft
keycode  27  =  apostrophe   quotedbl  bracketright braceright
keycode  43  =  backslash    bar       backslash    bar

keycode  30  =  a           A          a          A
keycode  31  =  r           R          s          S
keycode  32  =  s           S          d          D
keycode  33  =  t           T          f          F
keycode  34  =  g           G          g          G
keycode  35  =  Return      braceright h          H
keycode  36  =  k           K          j          J
keycode  37  =  n           N          k          K
keycode  38  =  e           E          l          L
keycode  39  =  i           I          semicolon  colon
keycode  40  =  o           O          apostrophe quotedbl
# replace enter with '
keycode  28  =  apostrophe  quotedbl   Return     Return

keycode  44  =  x       X        z      Z
keycode  45  =  c       C        x      X
keycode  46  =  d       D        c      C
keycode  47  =  v       V        v      V
keycode  48  =  z       Z        b      B
keycode  49  =  slash   question n      N
keycode  50  =  m       M        m      M
keycode  51  =  h       H        comma  less
keycode  52  =  comma   less     period greater
keycode  53  =  period  greater slash question
# make right shift /; I don't use rsft in qmk
keycode  54  =  slash   question

keycode  57  =  space space space space

# qwerty layer (removed nav layer, so this isn't really useful anymore)
keycode  58 = AltGr

keycode   1 = Escape
keycode  14 = Delete
# Tab to switch layout to qwerty so can use QMK keyboard
keycode  15 = AltGr_Lock
# keycode  28 = Return
        # alt     keycode  28 = Meta_Control_m
keycode  29 = Control
keycode  42 = Shift
# keycode  54 = Shift
keycode  56 = Alt
keycode  97 = Control

# muhenkan
keycode  94 = Shift

# Local Variables:
# mode: conf-unix
# End:
